     6→import * as readline from 'readline';
     7→import NexusLexer from '../lexer/nexus-lexer';
     8→import { NexusParser } from '../parser/nexus-parser';
     9→import { NexusCodegen } from '../codegen/nexus-codegen';
    10→import { NexusRunner } from '../runtime/nexus-runner';
    11→
    12→const HELP_TEXT = `FreeLang Nexus REPL 커맨드:
    13→  /mode v        V 모드로 전환 (기본)
    14→  /mode python   Python 모드로 전환
    15→  /mode          현재 모드 확인
    16→  /help          이 도움말
    17→  /exit          종료`;
    18→
    19→export class NexusRepl {
    20→  private mode: 'v' | 'python' = 'v';
    21→  private runner = new NexusRunner();
    22→  private buffer: string[] = [];
    23→
    24→  /**
    25→   * 입력 한 줄 평가
    26→   * readline 없이 호출 가능 → 단위 테스트 가능
    27→   */
    28→  eval(input: string): string {
    29→    // 커맨드 처리
    30→    if (input.startsWith('/')) {
    31→      return this.handleCommand(input.trim());
    32→    }
    33→
    34→    // @mode(v) 또는 @mode(python) 자동 삽입 후 파이프라인 실행
    35→    const source = `@mode(${this.mode})\n${input}`;
    36→
    37→    try {
    38→      const tokens = new NexusLexer(source).tokenize();
    39→      const ast = new NexusParser(tokens).parse();
    40→      const result = new NexusCodegen().generateProgram(ast);
    41→      const runResult = this.runner.run(result);
    42→
    43→      // 에러 확인
    44→      if (runResult.errors.length > 0) {
    45→        return `❌ ${runResult.errors.join('\n')}`;
    46→      }
    47→
    48→      // 출력 결합
    49→      const out = [runResult.cOutput, runResult.pythonOutput]
    50→        .filter(Boolean)
    51→        .join('\n')
    52→        .trim();
    53→
    54→      return out || '(no output)';
    55→    } catch (e) {
    56→      return `❌ ${(e as Error).message}`;
    57→    }
    58→  }
    59→
    60→  /**
    61→   * REPL 메타 커맨드 처리
    62→   */
    63→  handleCommand(cmd: string): string {
    64→    if (cmd === '/mode v') {
    65→      this.mode = 'v';
    66→      return '모드: V';
    67→    }
    68→    if (cmd === '/mode python') {
    69→      this.mode = 'python';
    70→      return '모드: Python';
    71→    }
    72→    if (cmd === '/mode') {
    73→      return `현재 모드: ${this.mode}`;
    74→    }
    75→    if (cmd === '/help') {
    76→      return HELP_TEXT;
    77→    }
    78→    return `알 수 없는 커맨드: ${cmd}. /help 참고`;
    79→  }
    80→
    81→  /**
    82→   * 현재 모드 반환 (테스트용)
    83→   */
    84→  getMode(): string {
    85→    return this.mode;
    86→  }
    87→
    88→  /**
    89→   * REPL 시작 (readline 루프)
    90→   */
    91→  start(): void {
    92→    console.log('FreeLang Nexus REPL v1.0.0  (/help 도움말  /exit 종료)');
    93→
    94→    const rl = readline.createInterface({
    95→      input: process.stdin,
    96→      output: process.stdout,
    97→    });
    98→
    99→    const getPrompt = () => (this.buffer.length > 0 ? '...   ' : `${this.mode}> `);
   100→
   101→    const ask = () => {
   102→      rl.question(getPrompt(), (line) => {
   103→        // 종료
   104→        if (line === '/exit' || line === '.exit') {
   105→          rl.close();
   106→          return;
   107→        }
   108→
   109→        // 멀티라인 감지: ':' 로 끝나면 계속 입력
   110→        if (line.endsWith(':')) {
