   121→        // 제출: 버퍼 + 현재 줄 합쳐서 실행
   122→        const full = this.buffer.length > 0 ? [...this.buffer, line].join('\n') : line;
   123→        this.buffer = [];
   124→
   125→        if (full.trim()) {
